async function adminView(){if(!state.adminSession)return loginView('admin');wrap(intro('OPERATIONS OVERVIEW','Kampanye berjalan. Anda memegang kendali.','Tinjau materi, konfirmasi penerimaan dana, dan pantau jaringan.',`<div class="actions"><button class="btn ghost" onclick="logout()">Keluar</button><button class="btn" onclick="nav('schedule')">Jadwal jaringan ↗</button></div>`)+`<div id="dashboard" class="loading">Memuat operasional…</div>`);try{const [summary,orders,screens]=await Promise.all([api('/admin/summary','GET',null,true),api('/admin/orders','GET',null,true),api('/admin/screens','GET',null,true)]);if(state.page!=='admin')return;$('#dashboard').className='';$('#dashboard').innerHTML=`<div class="stats">${[['Total pesanan',summary.orders],['Pembayaran tercatat',fmt(summary.revenue)],['Materi perlu review',summary.reviews],['Layar jaringan',summary.screens]].map(([label,value])=>`<div class="stat"><span class="muted">${label}</span><strong>${value}</strong></div>`).join('')}</div><section class="panel"><div class="section-head" style="margin-top:0"><div><h2>Aktivitas kampanye</h2><p class="muted">Tinjau materi sebelum menyetujui penayangan.</p></div><button class="btn ghost" onclick="adminView()">↻ Refresh</button></div><div class="table-wrap"><table class="table"><thead><tr><th>KAMPANYE / PENGIKLAN</th><th>LAYAR</th><th>JADWAL MULAI</th><th>STATUS</th><th>TOTAL</th><th>AKSI</th></tr></thead><tbody>${orders.map(o=>`<tr><td><b>${esc(o.company)}</b><div class="micro">${esc(o.order_no)}</div></td><td>${esc(screens.find(s=>s.id===o.screen_id)?.code||'')}</td><td>${dateTime(o.start_at)}</td><td>${badge(o.status)}</td><td>${fmt(o.total)}</td><td><button class="btn secondary" onclick="inspectOrder('${o.id}')">${o.status==='NEEDS_REVIEW'?'Tinjau materi':o.status==='AWAITING_PAYMENT'?'Verifikasi pembayaran':'Detail'}</button></td></tr>`).join('')||'<tr><td colspan="6">Belum ada kampanye. Pesanan baru akan muncul di sini.</td></tr>'}</tbody></table></div></section><div class="two"><section class="panel"><h2>QR pemesanan per layar</h2><p class="muted">Tautan langsung ke lokasi untuk calon pengiklan.</p><div class="grid">${screens.map(s=>`<div><img class="qr" src="/api/v1/screens/${s.id}/qr" alt="QR pemesanan ${esc(s.name)}"><h3>${esc(s.code)}</h3><p class="micro">${esc(s.name)}</p></div>`).join('')}</div></section><section class="panel"><h2>Alur operasional</h2><div class="timeline"><p>Tinjau materi<small>Pastikan konten dan format sesuai sebelum menyetujui.</small></p><p>Konfirmasi penerimaan dana<small>Cocokkan nominal dan referensi di mutasi bank Anda.</small></p><p>Pantau perangkat<small>Periksa heartbeat dan catatan penayangan pada halaman jadwal.</small></p></div><button class="btn ghost" onclick="showAudit()">Lihat log aktivitas →</button></section></div>`;}catch(e){fail(e);if(!state.adminSession)loginView('admin');}}
let inspectedOrder=null,reviewAssetUrl=null;
async function inspectOrder(id){try{const o=await api('/orders/'+id,'GET',null,true);inspectedOrder=o;const modal=$('#modal');$('#modalBody').innerHTML=`<div class="eyebrow">${esc(o.order_no)}</div><h2 id="modalTitle">${esc(o.company)}</h2>${badge(o.status)}<p class="micro">${esc(o.pic)} · ${esc(o.email)} · ${esc(o.phone)}</p><p class="micro">${dateTime(o.start_at)} → ${dateTime(o.end_at)}</p>${o.content_file?'<div id="reviewAsset" class="preview">Memuat materi…</div>':`<div class="preview"><h2>${esc(o.content_title||'Belum ada materi')}</h2><p>${esc(o.content_text||'')}</p></div>`}<div style="margin-top:18px">${summaryHtml(o)}</div>${o.status==='NEEDS_REVIEW'?`<form id="reviewForm"><div class="field" style="margin-top:18px"><label for="reviewReason">Catatan peninjauan (wajib jika ditolak)</label><textarea id="reviewReason" maxlength="500" placeholder="Alasan dan revisi yang diperlukan"></textarea></div><div class="actions"><button type="button" class="btn danger" onclick="decideReview('REJECT',this)">Minta revisi</button><button type="button" class="btn" onclick="decideReview('APPROVE',this)">Setujui materi</button></div></form>`:''}${o.status==='AWAITING_PAYMENT'?`<form id="paymentConfirm" style="margin-top:20px"><h3>Konfirmasi dana diterima</h3><p class="micro">Periksa mutasi rekening bank. Konfirmasi ini mengaktifkan jadwal.</p><div class="field"><label for="bankReference">Referensi transaksi bank</label><input id="bankReference" minlength="6" maxlength="120" required placeholder="Referensi unik dari mutasi bank"></div><div class="field"><label for="bankAmount">Nominal diterima (rupiah)</label><input id="bankAmount" type="number" min="1" required placeholder="${o.total}"></div><button type="submit" class="btn">Konfirmasi penerimaan dana</button></form>`:''}${['SCHEDULED','LIVE'].includes(o.status)?`<div class="field" style="margin-top:20px"><label for="takedownReason">Alasan penghentian</label><input id="takedownReason" placeholder="Wajib diisi untuk menghentikan kampanye"></div><button class="btn danger" onclick="takeDown('${o.id}',this)">Hentikan penayangan</button>`:''}<p class="error-text" id="inspectError" role="alert"></p>`;if(!modal.open)modal.showModal();if($('#paymentConfirm'))$('#paymentConfirm').onsubmit=confirmBankPayment;if(o.content_file){const response=await fetch('/api/v1/orders/'+id+'/creative',{credentials:'same-origin'});if(!response.ok)throw Error('Materi tidak dapat dimuat');if(reviewAssetUrl)URL.revokeObjectURL(reviewAssetUrl);reviewAssetUrl=URL.createObjectURL(await response.blob());$('#reviewAsset').innerHTML=o.content_mime==='video/mp4'?`<video src="${reviewAssetUrl}" controls playsinline></video>`:`<img src="${reviewAssetUrl}" alt="Materi yang diajukan ${esc(o.company)}">`;}}catch(e){fail(e);}}
async function decideReview(decision,button){const reason=$('#reviewReason').value.trim();if(decision==='REJECT'&&!reason){$('#inspectError').textContent='Isi alasan revisi terlebih dahulu.';return;}button.disabled=true;try{await api('/admin/moderation/'+inspectedOrder.id+'/decision','POST',{decision,reason},true);$('#modal').close();toast('Keputusan tersimpan');adminView();}catch(e){$('#inspectError').textContent=e.message;button.disabled=false;}}
async function confirmBankPayment(event){event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;try{await api('/admin/orders/'+inspectedOrder.id+'/confirm-payment','POST',{reference:$('#bankReference').value,amount:Number($('#bankAmount').value)},true);$('#modal').close();toast('Pembayaran dikonfirmasi. Kampanye terjadwal.');adminView();}catch(e){$('#inspectError').textContent=e.message;button.disabled=false;}}
async function takeDown(id,button){const reason=$('#takedownReason').value.trim();if(!reason){$('#inspectError').textContent='Isi alasan penghentian.';return;}button.disabled=true;try{await api('/admin/orders/'+id+'/takedown','POST',{reason},true);$('#modal').close();toast('Penayangan dihentikan');render();}catch(e){$('#inspectError').textContent=e.message;button.disabled=false;}}
async function showAudit(){try{const records=await api('/admin/audit','GET',null,true);$('#modalBody').innerHTML=`<h2 id="modalTitle">Log aktivitas</h2><div class="timeline">${records.map(r=>`<p>${esc(r.action)}<small>${dateTime(r.created_at)} · ${esc(r.entity)}<br>${esc(r.detail)}</small></p>`).join('')||'<p>Belum ada aktivitas.</p>'}</div>`;$('#modal').showModal();}catch(e){fail(e);}}
let scheduleData;
async function scheduleView(date=''){if(!state.adminSession)return loginView('schedule');wrap(intro('NETWORK & SCHEDULING','Tepat waktu. Di layar yang tepat.','Pantau jadwal mingguan, koneksi perangkat, dan bukti penayangan.',`<button class="btn ghost" onclick="scheduleView(document.querySelector('#scheduleDate').value)">↻ Refresh</button>`)+`<section class="panel"><div class="row"><div><h2>Jadwal jaringan</h2><p class="micro">7 hari · WIB (UTC+7)</p></div><div class="toolbar"><label for="scheduleDate" class="micro">Mulai tanggal</label><input type="date" id="scheduleDate" value="${esc(date||new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Jakarta'}))}" onchange="scheduleView(this.value)" style="width:auto"><button class="btn secondary" onclick="blackoutForm()">＋ Blokir jadwal</button></div></div><div id="scheduleGrid" class="loading">Memuat jadwal…</div><p class="micro">Hijau: terjadwal / tayang · Kuning: menunggu pembayaran · Abu-abu: pemeliharaan</p></section><div class="two"><section class="panel"><div class="row"><h2>Status perangkat</h2><button class="btn secondary" onclick="deviceManager()">Kelola token</button></div><div id="deviceList"></div><p class="micro" id="schedulerStatus"></p></section><section class="panel"><h2>Catatan penayangan terakhir</h2><div id="playbackList"></div></section></div>`);try{const [data,logs]=await Promise.all([api('/admin/schedule'+(date?'?date='+encodeURIComponent(date):''),'GET',null,true),api('/admin/playback','GET',null,true)]);if(state.page!=='schedule')return;scheduleData=data;const days=Array.from({length:7},(_,i)=>new Date(new Date(data.start).getTime()+i*86400000));$('#scheduleGrid').className='table-wrap';$('#scheduleGrid').innerHTML=`<div class="schedule-grid"><div class="schedule-cell head">LAYAR / LOKASI</div>${days.map(day=>`<div class="schedule-cell head">${day.toLocaleDateString('id-ID',{timeZone:'Asia/Jakarta',weekday:'short',day:'numeric',month:'short'})}</div>`).join('')}${data.screens.map(screen=>`<div class="schedule-cell"><b>${esc(screen.code)}</b><p class="micro">${esc(screen.name)}</p></div>${days.map(day=>{const end=new Date(day.getTime()+86400000);return `<div class="schedule-cell">${data.orders.filter(o=>o.screen_id===screen.id&&new Date(o.start_at)<end&&new Date(o.end_at)>day).map(o=>`<div class="booking-block ${o.status==='AWAITING_PAYMENT'?'hold':''}"><b>${esc(o.company)}</b><br>${esc(labels[o.status])}<br>${new Date(o.start_at).toLocaleTimeString('id-ID',{timeZone:'Asia/Jakarta',hour:'2-digit',minute:'2-digit'})} → ${new Date(o.end_at).toLocaleTimeString('id-ID',{timeZone:'Asia/Jakarta',hour:'2-digit',minute:'2-digit'})}</div>`).join('')}${data.blackouts.filter(b=>b.screen_id===screen.id&&new Date(b.start_at)<end&&new Date(b.end_at)>day).map(b=>`<div class="booking-block blackout">${esc(b.reason)}<br><button class="text-button" onclick="removeBlackout('${b.id}')">Hapus blokir</button></div>`).join('')}</div>`;}).join('')}`).join('')}</div>`;$('#deviceList').innerHTML=data.screens.map(s=>`<div class="device"><span class="device-dot ${s.online?'online':''}"></span><div><b>${esc(s.name)}</b><small>${s.online?'Terhubung':'Tidak terhubung'} · ${s.last_seen?'Terakhir '+dateTime(s.last_seen):'Belum ada heartbeat'}</small></div></div>`).join('');$('#schedulerStatus').textContent='Scheduler terakhir: '+dateTime(data.scheduler.last_tick)+'. Rekonsiliasi otomatis setiap 5 detik.';$('#playbackList').innerHTML=logs.length?`<div class="timeline">${logs.slice(0,10).map(l=>`<p>${esc(data.screens.find(s=>s.id===l.screen_id)?.code||l.screen_id)} · ${esc(l.status)}<small>${dateTime(l.started_at)}<br>Pesanan ${esc(l.order_id?.slice(0,8))}</small></p>`).join('')}</div>`:'<div class="empty" style="padding:25px 0"><p>Belum ada catatan. Hubungkan player dan mulai kampanye terjadwal.</p><a class="btn secondary" href="/player" target="_blank" rel="noopener">Buka player ↗</a></div>';}catch(e){fail(e);if(!state.adminSession)loginView('schedule');}}
function blackoutForm(){if(!scheduleData)return;$('#modalBody').innerHTML=`<h2 id="modalTitle">Blokir jadwal layar</h2><p class="muted">Gunakan untuk pemeliharaan. Jadwal yang sudah dipesan tidak dapat ditimpa.</p><form id="blackoutForm"><div class="field"><label for="blackoutScreen">Layar</label><select id="blackoutScreen">${scheduleData.screens.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><div class="form-grid"><div class="field"><label for="blackoutStart">Mulai · waktu perangkat</label><input id="blackoutStart" type="datetime-local" required></div><div class="field"><label for="blackoutEnd">Selesai · waktu perangkat</label><input id="blackoutEnd" type="datetime-local" required></div></div><div class="field"><label for="blackoutReason">Alasan</label><input id="blackoutReason" required maxlength="500"></div><p class="error-text" id="blackoutError" role="alert"></p><button class="btn" type="submit">Simpan blokir</button></form>`;$('#modal').showModal();$('#blackoutForm').onsubmit=async e=>{e.preventDefault();try{await api('/admin/blackouts','POST',{screen_id:$('#blackoutScreen').value,start_at:new Date($('#blackoutStart').value).toISOString(),end_at:new Date($('#blackoutEnd').value).toISOString(),reason:$('#blackoutReason').value},true);$('#modal').close();scheduleView($('#scheduleDate').value);}catch(err){$('#blackoutError').textContent=err.message;}};}
async function removeBlackout(id){try{await api('/admin/blackouts/'+id,'DELETE',null,true);toast('Blokir dihapus');scheduleView($('#scheduleDate').value);}catch(e){fail(e);}}
function legalContent(type){const privacy=type==='privacy',c=state.config;return `<div class="eyebrow">VERSI ${esc(c.terms_version)}</div><h2 id="modalTitle">${privacy?'Kebijakan Privasi':'Syarat & Ketentuan'}</h2>${!c.legal_configured?'<div class="notice">Draf operasional. Identitas badan usaha dan kontak layanan belum dikonfigurasi. Operator harus melengkapi dan meninjau dokumen ini sebelum peluncuran publik.</div>':''}${privacy?`<p>${esc(c.operator)} menggunakan informasi yang Anda masukkan untuk memproses pesanan dan mengoperasikan layanan penayangan.</p><h3>Data yang diproses</h3><p>Nama perusahaan, alamat, PIC, email, nomor telepon, jadwal, materi, transaksi, serta catatan persetujuan dan aktivitas. NPWP disimpan sebagai hash dan empat digit terakhir. Kode verifikasi disimpan sebagai hash.</p><h3>Tujuan & akses</h3><p>Data digunakan untuk verifikasi kontak, peninjauan materi, penagihan, penjadwalan, serta penanganan kendala. Operator yang berwenang dapat mengakses data pesanan. Penyedia pengiriman menerima email atau nomor tujuan dan kode verifikasi jika integrasi diaktifkan.</p><h3>Penyimpanan & kontrol</h3><p>Token sesi disimpan di sessionStorage browser. Menutup sesi dapat menghilangkan akses pesanan dari perangkat ini. Data pesanan dan materi disimpan pada server operator. Kebijakan masa retensi harus ditetapkan operator sebelum peluncuran publik.</p><h3>Permintaan terkait data</h3><p>Untuk koreksi, permintaan penghapusan, atau pertanyaan penggunaan data, hubungi operator dengan nomor pesanan. Permintaan penghapusan ditinjau terhadap kebutuhan penyelesaian transaksi dan kewajiban penyimpanan yang berlaku.</p>`:`<p>Ketentuan ini menjelaskan proses pemesanan ruang iklan videotron melalui ${esc(c.operator)}. Persetujuan dan versi dokumen dicatat bersama pesanan.</p><h3>1. Pemesanan & ketersediaan</h3><p>Pengiklan wajib memberikan informasi perusahaan dan kontak yang benar. Jadwal dimulai minimal 24 jam setelah pemesanan dan berlangsung minimal 24 jam. Draft pesanan belum mengunci slot. Ketersediaan diperiksa kembali saat checkout.</p><h3>2. Materi & peninjauan</h3><p>Pengiklan bertanggung jawab atas hak penggunaan materi dan kebenaran klaim iklan. Konten ilegal, pornografi, perjudian, dan materi yang melanggar hak pihak lain tidak diperbolehkan. Semua materi memerlukan persetujuan operator. Materi yang ditolak dapat direvisi dan diajukan ulang sebelum pembayaran.</p><h3>3. Tarif & pembayaran</h3><p>Tarif dihitung prorata menurut jumlah hari dalam bulan, durasi per hari kalender WIB, dan pembulatan setiap hari. Pajak ditampilkan pada rincian pesanan sesuai konfigurasi operator. Checkout mengunci slot selama 15 menit. Jadwal aktif setelah penerimaan dana dikonfirmasi. Bukti pembayaran aplikasi bukan faktur pajak.</p><h3>4. Penayangan & gangguan</h3><p>Player menayangkan materi yang disetujui pada periode pesanan. Penayangan bergantung pada konektivitas, kesiapan perangkat, dan kondisi lokasi. Gangguan, permintaan perubahan, serta klaim selisih penayangan dilaporkan dengan nomor pesanan dan waktu kejadian untuk ditinjau operator.</p><h3>5. Pembatalan & penyelesaian</h3><p>Perubahan setelah pembayaran, pembatalan, dan permintaan pengembalian dana ditangani operator secara manual. Persetujuan atau nominal pengembalian tidak ditentukan otomatis oleh aplikasi. Jika dana diterima setelah tagihan kedaluwarsa, hubungi operator untuk rekonsiliasi sebelum membuat pembayaran lain.</p><h3>6. Penghentian materi</h3><p>Operator dapat menghentikan materi yang melanggar ketentuan dan mencatat alasan tindakan. Hubungi layanan operator untuk klarifikasi atau tindak lanjut.</p>`}<h3>Kontak operator</h3><p>${esc(c.operator)}<br>${c.support_email?esc(c.support_email):'Kontak belum ditetapkan oleh operator.'}</p>`;}
function showLegal(type){$('#modalBody').innerHTML=legalContent(type);$('#modal').showModal();}
function showGuide(){LamiaGuide.open({bookingPolicy:state.config.booking_policy,onStart:()=>{state.step=1;nav('booking');$('#view').focus();}});}
async function init(){try{[state.config,state.screens]=await Promise.all([api('/config'),api('/screens')]);VistaraDates.configure(state.config.booking_policy||{});await restoreAdminSession();$('#environment').textContent=state.config.demo_otp||state.config.demo_payments?'PENGUJIAN LOKAL':'WIB · UTC+7';const token=new URLSearchParams(location.search).get('screen_token');if(location.pathname==='/status'){orderStatusAccess=new URLSearchParams(location.hash.slice(1)).get('access');history.replaceState(null,'',location.pathname);trackOrderStatus();return;}if(location.pathname==='/terms'||location.pathname==='/privacy'){wrap(`<article class="panel legal-copy">${legalContent(location.pathname.slice(1))}</article>`);return;}if(token){const screen=await api('/screens/by-token/'+encodeURIComponent(token));choose(screen.id);return;}if(location.pathname==='/login'){const next=new URLSearchParams(location.search).get('next');const destination=['admin','schedule','player'].includes(next)?next:'admin';if(state.adminSession){if(destination==='player')location.assign('/player');else nav(destination);}else loginView(destination);return;}if(location.pathname==='/admin'||location.pathname==='/schedule'){nav(location.pathname==='/admin'?'admin':'schedule');return;}home();}catch(e){wrap(`<section class="panel empty"><h1 class="heading">Workspace belum terhubung</h1><p>${esc(e.message)}</p><button class="btn" onclick="init()">Coba lagi</button></section>`);}}
init();
async function deviceManager(){try{const devices=await api('/admin/devices','GET',null,true);$('#modalBody').innerHTML=`<h2 id="modalTitle">Token perangkat</h2><p class="micro">Setiap token hanya dapat mengakses satu layar. Token baru ditampilkan sekali; simpan pada player yang sesuai.</p><form id="enrollDevice"><div class="field"><label for="deviceScreen">Layar</label><select id="deviceScreen">${state.screens.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label for="deviceName">Nama perangkat</label><input id="deviceName" required maxlength="120" placeholder="Contoh: Player Tengah Kota 01"></div><button class="btn" type="submit">Buat token perangkat</button></form><div id="newDeviceToken"></div><div class="divider"></div><h3>Perangkat terdaftar</h3>${devices.map(d=>`<div class="device"><div><b>${esc(d.name)}</b><small>${esc(state.screens.find(s=>s.id===d.screen_id)?.code||'')} · ${d.revoked_at?'Token dicabut':'Aktif'}</small></div>${!d.revoked_at?`<button class="btn danger" style="margin-left:auto" onclick="revokeDevice('${d.id}',this)">Cabut</button>`:''}</div>`).join('')||'<p class="micro">Belum ada perangkat terdaftar.</p>'}`;if(!$('#modal').open)$('#modal').showModal();$('#enrollDevice').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;try{const device=await api('/admin/devices','POST',{screen_id:$('#deviceScreen').value,name:$('#deviceName').value},true);$('#newDeviceToken').innerHTML=`<div class="notice success"><b>Token ${esc(device.name)}</b><p>Simpan sekarang. Token tidak dapat dilihat ulang.</p><textarea readonly aria-label="Token perangkat baru" style="min-height:65px;word-break:break-all">${esc(device.token)}</textarea></div>`;button.textContent='Token berhasil dibuat';}catch(e){fail(e);button.disabled=false;}};}catch(e){fail(e);}}
async function revokeDevice(id,button){button.disabled=true;try{await api('/admin/devices/'+id,'DELETE',null,true);button.textContent='Dicabut';toast('Token dicabut. Player akan berhenti saat sinkron berikutnya.');}catch(e){fail(e);button.disabled=false;}}


async function trackOrderStatus(){
  state.page='status';$('#crumb').textContent='Status pesanan';
  wrap(intro('PERKEMBANGAN KAMPANYE','Status pesanan Anda.','Pantau review materi dan perkembangan kampanye dari halaman ini.')+'<section class="panel" id="trackingStatus"><p class="muted">Memeriksa status terbaru…</p></section>');
  if(!orderStatusAccess){$('#trackingStatus').innerHTML='<h2>Buka tautan dari email terbaru.</h2><p class="muted">Tautan status tersedia pada email penerimaan atau keputusan review materi.</p>';return;}
  try{
    const response=await fetch('/api/v1/order-status',{credentials:'omit',headers:{'X-Order-Status':orderStatusAccess}});
    const order=await response.json();
    if(!response.ok)throw Error(order.detail||'Status belum dapat dimuat.');
    if(state.page!=='status')return;
    $('#trackingStatus').innerHTML=`<div class="row"><div><div class="eyebrow">${esc(order.order_no)}</div><h2>${esc(order.content_title||'Kampanye Anda')}</h2></div>${badge(order.status)}</div><p class="muted">${esc(order.screen)}</p><div class="summary"><p class="micro">${dateTime(order.start_at)} → ${dateTime(order.end_at)}</p><p style="margin:0">${order.status==='NEEDS_REVIEW'?'Materi sedang ditinjau operator. Kami akan mengirim email saat keputusan tersedia.':order.status==='APPROVED'?'Materi telah disetujui. Lanjutkan checkout dari Pesanan saya.':order.status==='CONTENT_REJECTED'?'Materi memerlukan revisi. Perbaiki melalui detail pesanan, lalu ajukan kembali.':esc(labels[order.status]||order.status)}</p></div>${order.review_note?`<div class="notice"><b>Catatan revisi</b><p style="margin:6px 0 0">${esc(order.review_note)}</p></div>`:''}<div class="timeline">${order.history.map(event=>`<p>${esc(labels[event.to_status]||event.to_status)}<small>${dateTime(event.created_at)}</small></p>`).join('')}</div><p class="micro">Halaman diperbarui otomatis setiap 20 detik. Untuk mengubah materi atau membayar, buka Pesanan saya pada sesi pemesanan Anda.</p><div class="actions"><button class="btn ghost" onclick="trackOrderStatus()">↻ Perbarui status</button><button class="btn" onclick="nav('orders')">Buka Pesanan saya →</button></div>`;
    orderStatusTimer=setInterval(()=>{if(document.visibilityState==='visible')trackOrderStatus();},20000);
  }catch(error){if(state.page==='status')$('#trackingStatus').innerHTML=`<h2>Status belum dapat ditampilkan.</h2><p class="error-text">${esc(error.message)}</p><button class="btn ghost" onclick="trackOrderStatus()">Coba lagi</button>`;}
}
